-- Dev seed (profile `local` only) — Finance workstream: escrow, ledger, payouts, refunds and disputes for the three
-- V100 businesses. Generated by a script (see docs/DECISIONS.md, Finance workstream); amounts in cents.
--
-- Prairie Wrench reproduces design 02: "$2,140.60 releasing Friday" (= $822.60 released + $1,318.00 in escrow ·
-- 11 jobs), take rate 9 % (Master), "$160.00 on hold · 1 dispute" (DS-1188, A. Osei); payouts $1,912.40 · 14 jobs,
-- $2,204.15 · 16, $1,655.90 · 12, $1,980.00 · 13; last 90 days: $19,440 gross (+22 %), 118 jobs & orders, $164.75
-- average, 71 % repeat customers, 2.4 % refund rate, by listing 5,820 / 4,120 / 3,480 / 2,880 / 1,980 / 1,160,
-- sources 54 / 31 / 11 / 4 %; history RF-2201, RF-2188, DS-1102. Every time is relative to when the seed runs.
DO $seed$
DECLARE
  v_now  timestamptz := now();
  v_today date := (now() AT TIME ZONE 'America/Edmonton')::date;
  v_day0 timestamptz := (((now() AT TIME ZONE 'America/Edmonton')::date)::timestamp AT TIME ZONE 'America/Edmonton');
  v_next timestamptz;
  v_last timestamptz;
  v_hwin interval;
  v_osei text;
  v_amt bigint;
  v_n integer;
  w_end timestamptz;
  m text;
  k integer;
  po text;
BEGIN
  -- next Friday 09:00 Edmonton strictly after now (the default weekly schedule); the last payout a week before
  v_next := ((v_today + ((5 - extract(isodow FROM v_today)::int + 7) % 7))::timestamp + time '09:00') AT TIME ZONE 'America/Edmonton';
  IF v_next <= v_now THEN v_next := v_next + interval '7 days'; END IF;
  v_last := v_next - interval '7 days';
  -- held escrow releases before Friday's payout whenever there is time for it
  v_hwin := least(interval '47 hours', greatest(interval '1 hour', v_next - v_now - interval '30 minutes'));

  -- Stripe Connect Express accounts, bank accounts, schedules
         holder_name, external_ref, state, created_at, created_by, confirmed_at, effective_at) VALUES
    ('01M1D480HF635M5V9A8WNR0M1N', '01J9ZD3V00000000000000PWM1', 'manual', 'TD Canada Trust', '004', '10009', '3391', 'Prairie Wrench Mobile Mechanics Ltd.', 'ba_seedPrairieTD3391', 'active', '2026-01-06T17:00:00Z', '01J9ZD3V00000000000000RAV1', '2026-01-06T17:00:00Z', '2026-01-07T17:00:00Z'),
    ('01M1D480HG4WKFGJDVJVVZHB0H', '01J9ZD3V00000000000000PWP1', 'manual', 'TD Canada Trust', '004', '10009', '3391', 'Prairie Wrench Mobile Mechanics Ltd.', 'ba_seedPartsTD3391', 'active', '2026-01-06T17:01:00Z', '01J9ZD3V00000000000000RAV1', '2026-01-06T17:01:00Z', '2026-01-07T17:01:00Z'),
    ('01M1D480HHNWBNRKRCZXXKWYHQ', '01J9ZD3V00000000000000PDB1', 'instant', 'ATB Financial', '219', '07149', '7714', 'Ravi Sandhu', 'ba_seedPhoATB7714', 'active', '2026-01-06T17:02:00Z', '01J9ZD3V00000000000000RAV1', '2026-01-06T17:02:00Z', '2026-01-07T17:02:00Z');

  -- ── escrows (+ their PaymentIntent mirrors) ──

  -- transfers to the connected accounts for every released escrow
  SELECT 'TR' || substr(e.id, 3), e.id, 'tr_seed_' || e.id, e.amount_cents, e.fee_cents, e.amount_cents - e.fee_cents, e.released_at
    FROM payments.escrows e WHERE e.merchant_id IN ('01J9ZD3V00000000000000PWM1', '01J9ZD3V00000000000000PWP1', '01J9ZD3V00000000000000PDB1')
     AND e.state = 'released';

  -- ledger: capture into escrow at fulfilment, release to the merchant (net) + Northline's fee
  SELECT 'LC' || substr(e.id, 3) || x.n, x.account, x.debit, x.credit, 'escrow', e.id, e.fulfilled_at
    FROM payments.escrows e
    CROSS JOIN LATERAL (VALUES (1, 'stripe_balance', e.amount_cents + e.tax_cents, 0::bigint),
                               (2, 'escrow', 0::bigint, e.amount_cents),
                               (3, 'tax_payable', 0::bigint, e.tax_cents)) AS x(n, account, debit, credit)
   WHERE e.merchant_id IN ('01J9ZD3V00000000000000PWM1', '01J9ZD3V00000000000000PWP1', '01J9ZD3V00000000000000PDB1')
     AND e.fulfilled_at IS NOT NULL AND (x.debit > 0 OR x.credit > 0);
  SELECT 'LR' || substr(e.id, 3) || x.n, x.account, x.debit, x.credit, 'escrow', e.id, e.released_at
    FROM payments.escrows e
    CROSS JOIN LATERAL (VALUES (1, 'escrow', e.amount_cents, 0::bigint),
                               (2, 'merchant:' || e.merchant_id, 0::bigint, e.amount_cents - e.fee_cents),
                               (3, 'revenue', 0::bigint, e.fee_cents)) AS x(n, account, debit, credit)
   WHERE e.merchant_id IN ('01J9ZD3V00000000000000PWM1', '01J9ZD3V00000000000000PWP1', '01J9ZD3V00000000000000PDB1')
     AND e.state = 'released' AND (x.debit > 0 OR x.credit > 0);


  -- ── refunds (never instant: seller review → queue → paid) ──

  -- ── disputes ──
  v_osei := '01M1D486REDKTNJY56SF243N3Z';
         customer_name, customer_statement, response, response_updated_at, respond_by, opened_at) VALUES (
    v_osei, 'escrow', '01M1D47Z2HW57KN5A7R30F02HK', '01M1D480HKY5A174D08XYJP1Z9',
    replace(replace('[{"id":"01M1D486R07866615T1XBMAEFC","kind":"photo","name":"IMG_2201.jpg","contentType":"image/jpeg","size":911273,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R19YGCZ42YB1BSHYRD","kind":"photo","name":"IMG_2202.jpg","contentType":"image/jpeg","size":2520374,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R2ARPRQYNVA4Q0NP3B","kind":"photo","name":"IMG_2203.jpg","contentType":"image/jpeg","size":3299673,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R37C5ZR8QXYKCTV9W7","kind":"photo","name":"IMG_2204.jpg","contentType":"image/jpeg","size":2195644,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R4N2CTAY47E16A9K0G","kind":"photo","name":"IMG_2205.jpg","contentType":"image/jpeg","size":2424430,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R59XYD0NAMA25C5WJS","kind":"photo","name":"IMG_2206.jpg","contentType":"image/jpeg","size":2706760,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R6A0D9W42HQYTCB4C2","kind":"photo","name":"IMG_2207.jpg","contentType":"image/jpeg","size":1199750,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R7FX9F39Q3JWA8Y6JR","kind":"photo","name":"IMG_2208.jpg","contentType":"image/jpeg","size":1889610,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R8M3C9EYWS42VHWYZ5","kind":"photo","name":"IMG_2209.jpg","contentType":"image/jpeg","size":1943599,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486R9T6W1XND5FTZ9BZF4","kind":"photo","name":"IMG_2210.jpg","contentType":"image/jpeg","size":2896738,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486RA0DJNKT4DE0W35FCG","kind":"photo","name":"IMG_2211.jpg","contentType":"image/jpeg","size":3080371,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486RBWMDT8J7A7QHN54G3","kind":"photo","name":"IMG_2212.jpg","contentType":"image/jpeg","size":2748904,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486RCSVCXZ6B4XT4KJERV","kind":"report","name":"Inspection report.pdf","contentType":"application/pdf","size":482113,"by":"merchant","at":"__AT__","storageKey":null},{"id":"01M1D486RD3SM9BNQ4DG7Q0NDZ","kind":"gps","name":"GPS check-in","contentType":null,"size":0,"by":"merchant","at":"__GPS__","storageKey":null}]', '__AT__', to_char(((v_day0 - interval '5 days' + interval '13 hours 30 minutes') + interval '44 minutes') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')),
            '__GPS__', to_char(((v_day0 - interval '5 days' + interval '13 hours 30 minutes') + interval '28 minutes') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))::jsonb,
    'open', '01J9ZD3V00000000000000PWM1', 'DS-1188', 'Pre-purchase inspection', 16000, 'A. Osei',
    'Report missed a coolant leak the dealer found two days later.',
    format('Inspection photos show dry hoses at 2:14 pm on %s; leak likely developed after. Offering 50%% goodwill refund.',
           to_char((v_day0 - interval '5 days' + interval '13 hours 30 minutes') AT TIME ZONE 'America/Edmonton', 'Mon FMDD')),
    v_now - interval '3 hours', v_now + interval '52 hours', v_now - interval '20 hours');
         subject, amount_cents, customer_name, customer_statement, response, refund_cents, respond_by, opened_at, decided_at) VALUES (
    '01M1D486RGWSW3Q7YYJH3NDA06', 'escrow', '01M1D47Z3610HKJS9RZ53QET4T', '01M1D480Y704Z9MS44M0C5G54Z', '[]'::jsonb, 'decided', 'release',
    '01J9ZD3V00000000000000RAV1', '01J9ZD3V00000000000000PWM1', 'DS-1102', 'Diagnostic disagreement', 15800, 'L. Bouchard',
    'The scan found nothing and I still had the warning light.',
    'Scan log attached: two stored codes cleared, light off at hand-over.', 0,
    (v_day0 - interval '46 days' + interval '566 minutes') + interval '4 days', (v_day0 - interval '46 days' + interval '566 minutes') + interval '1 day', (v_day0 - interval '46 days' + interval '566 minutes') + interval '3 days');


  -- ── payouts: every Friday 09:00 the whole balance goes to the bank (the last four are the design's) ──
  FOREACH m IN ARRAY ARRAY['01J9ZD3V00000000000000PWM1', '01J9ZD3V00000000000000PWP1', '01J9ZD3V00000000000000PDB1'] LOOP
    FOR k IN REVERSE 56..1 LOOP
      w_end := v_next - make_interval(days => 7 * k);
      CONTINUE WHEN m = '01J9ZD3V00000000000000PWM1' AND k <= 4;
      SELECT coalesce(sum(credit_cents - debit_cents), 0) INTO v_amt
        FROM payments.ledger_entries WHERE account = 'merchant:' || m AND at <= w_end;
      CONTINUE WHEN v_amt <= 0;
      SELECT count(*) INTO v_n FROM payments.escrows
       WHERE merchant_id = m AND state = 'released' AND released_at > w_end - interval '7 days' AND released_at <= w_end;
      po := 'PO' || substr(md5(m || k), 1, 24);
             item_count, payout_account_id, destination)
      SELECT upper(translate(po, 'ilou', 'jkmn')), m, 'po_' || substr(md5(po), 1, 4), v_amt, 'scheduled', 0, 'paid',
             w_end + interval '3 days', w_end, v_n, a.id,
             CASE WHEN a.institution_name = 'TD Canada Trust' THEN 'TD' ELSE a.institution_name END || ' ··' || a.last4
        FROM payments.payout_accounts a WHERE a.merchant_id = m AND a.state = 'active';
    END LOOP;
  END LOOP;

         item_count, payout_account_id, destination)
  SELECT '01M1D486RJPWV824B7WDHCB31E', '01J9ZD3V00000000000000PWM1', 'po_419n', 191240, 'scheduled', 0, 'paid', v_next - interval '4 days',
         v_next - interval '7 days', 14, a.id, 'TD ··3391'
    FROM payments.payout_accounts a WHERE a.merchant_id = '01J9ZD3V00000000000000PWM1' AND a.state = 'active';
         item_count, payout_account_id, destination)
  SELECT '01M1D486RPPM5C5X7PJBTF8WZA', '01J9ZD3V00000000000000PWM1', 'po_csjz', 220415, 'scheduled', 0, 'paid', v_next - interval '11 days',
         v_next - interval '14 days', 16, a.id, 'TD ··3391'
    FROM payments.payout_accounts a WHERE a.merchant_id = '01J9ZD3V00000000000000PWM1' AND a.state = 'active';
         item_count, payout_account_id, destination)
  SELECT '01M1D486RT2WG6XYJJ8DBV3JSZ', '01J9ZD3V00000000000000PWM1', 'po_np6r', 165590, 'scheduled', 0, 'paid', v_next - interval '18 days',
         v_next - interval '21 days', 12, a.id, 'TD ··3391'
    FROM payments.payout_accounts a WHERE a.merchant_id = '01J9ZD3V00000000000000PWM1' AND a.state = 'active';
         item_count, payout_account_id, destination)
  SELECT '01M1D486RY2MBYN0CY00GY30A2', '01J9ZD3V00000000000000PWM1', 'po_5e65', 198000, 'scheduled', 0, 'paid', v_next - interval '25 days',
         v_next - interval '28 days', 13, a.id, 'TD ··3391'
    FROM payments.payout_accounts a WHERE a.merchant_id = '01J9ZD3V00000000000000PWM1' AND a.state = 'active';

  -- sanity: the design's balance
  SELECT coalesce(sum(credit_cents - debit_cents), 0) INTO v_amt FROM payments.ledger_entries
   WHERE account = 'merchant:01J9ZD3V00000000000000PWM1';
  IF v_amt <> 82260 THEN RAISE EXCEPTION 'V105: Prairie Wrench balance is %, expected 82260', v_amt; END IF;
END
$seed$;
